#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;
    cout << n << " is " << ((n % 2 == 0) ? "even" : "odd") << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int a, b, c;
    cin >> a >> b >> c;
    int smallest = (a < b) ? ((a < c) ? a : c) : ((b < c) ? b : c);
    cout << "Smallest = " << smallest << endl;
    return 0;
}
